xml.Script:
        clSkyBlue := '0077DD';
        clYellow  := 'FFFF00';
        clBlue    := '0000FF';
        clWhite   := 'FFFFFF';

        K := 0.6;

        C23 := K * 0.83210907242821;

        D1 := C23;
        D2 := K * 0.75;
        D3 := K * 0.93;

        DCut1 := D1 - K * 0.1;
        DCut2 := D2 - K * 0.1;

        R := K  * 0.35;
        H := D3 * 1.05;

        Ang := Arccos(3 / sqrt(17));

        N := 40;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

